CREATE DATABASE IF NOT EXISTS raincheck CHARACTER SET utf8mb4;
USE raincheck;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('USER','ADMIN') DEFAULT 'USER',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE areas(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL);
CREATE TABLE reports(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,area_id INT NOT NULL,rain ENUM('NONE','LIGHT','MODERATE','HEAVY') NOT NULL,flood ENUM('NONE','ANKLE','KNEE','WAIST') NOT NULL DEFAULT 'NONE',note VARCHAR(255),photo VARCHAR(120),status ENUM('PENDING','VERIFIED','HIDDEN') DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(area_id) REFERENCES areas(id));
CREATE TABLE confirmations(report_id INT NOT NULL,user_id INT NOT NULL,PRIMARY KEY(report_id,user_id),FOREIGN KEY(report_id) REFERENCES reports(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
